arguments.cmd:
cat > /tmp/render_trade_svg.js <<'NODE'
const fs = require('fs');
const path = require('path');
const data = JSON.parse(fs.readFileSync('/app/benchmark/source_data.json','utf8'));
const outSvg = '/tmp/trade_chart.svg';
const outHtml = '/tmp/trade_chart.html';
const W = 3200, H = 2100;
const margin = {left: 180, right: 70, top: 220, bottom: 145};
const plotX0 = margin.left, plotX1 = W - margin.right;
const bg = '#FBFAF7';
const colors = {
  us:'#A33A32', cn:'#D8842A', trade:'#2F5D8C', import:'#6B8DB3', export:'#88A7C6',
  china:'#5B6472', vietnam:'#168C7A', india:'#7A63B8', alt:'#1B9E77', event:'#2F3640',
  review:'#6B7280', deal:'#2F7D50', grid:'#D8DEE8', axis:'#9AA4B2', shade:'#F5E6D3', recovery:'#E7F0F7', text:'#1F2933', sub:'#47515E'
};
const panels = {
  event: {y0: 245, y1: 430},
  tariff: {y0: 505, y1: 875},
  trade: {y0: 995, y1: 1365},
  share: {y0: 1485, y1: 1855}
};
const xmin=2016, xmax=2024.65;
const xScale = x => plotX0 + (x-xmin)/(xmax-xmin)*(plotX1-plotX0);
const yScale = (v, min, max, y0, y1) => y1 - (v-min)/(max-min)*(y1-y0);
const esc = s => String(s).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const fmt = n => Number(n).toLocaleString('en-US', {maximumFractionDigits:1, minimumFractionDigits: Number.isInteger(n)?0:1});
function decYear(dateStr){ const d=new Date(dateStr+'T00:00:00Z'); const s=new Date(Date.UTC(d.getUTCFullYear(),0,1)); const e=new Date(Date.UTC(d.getUTCFullYear()+1,0,1)); return d.getUTCFullYear() + (d-s)/(e-s); }
function periodX(p){ const [y,h]=p.split('-'); return +y + (h==='H1'?0.25:0.75); }
function linePath(xs, ys, ymin, ymax, y0, y1){ return xs.map((x,i)=>(i?'L':'M')+xScale(x).toFixed(1)+' '+yScale(ys[i],ymin,ymax,y0,y1).toFixed(1)).join(' '); }
function stepPath(xs, ys, ymin, ymax, y0, y1){
  let d = `M${xScale(xs[0]).toFixed(1)} ${yScale(ys[0],ymin,ymax,y0,y1).toFixed(1)}`;
  for(let i=1;i<xs.length;i++){
    const mid=(xs[i-1]+xs[i])/2;
    d += ` L${xScale(mid).toFixed(1)} ${yScale(ys[i-1],ymin,ymax,y0,y1).toFixed(1)}`;
    d += ` L${xScale(mid).toFixed(1)} ${yScale(ys[i],ymin,ymax,y0,y1).toFixed(1)}`;
    d += ` L${xScale(xs[i]).toFixed(1)} ${yScale(ys[i],ymin,ymax,y0,y1).toFixed(1)}`;
  }
  return d;
}
function areaPath(xs, ys, base, ymin, ymax, y0, y1){
  const top = xs.map((x,i)=>(i?'L':'M')+xScale(x).toFixed(1)+' '+yScale(ys[i],ymin,ymax,y0,y1).toFixed(1)).join(' ');
  return top + ` L${xScale(xs[xs.length-1]).toFixed(1)} ${yScale(base,ymin,ymax,y0,y1).toFixed(1)} L${xScale(xs[0]).toFixed(1)} ${yScale(base,ymin,ymax,y0,y1).toFixed(1)} Z`;
}
function text(x,y,content,opts={}){
  const {size=24, fill=colors.text, weight='400', anchor='start', cls='', opacity=1} = opts;
  return `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" font-weight="${weight}" text-anchor="${anchor}" opacity="${opacity}" class="${cls}">${esc(content)}</text>`;
}
function multiText(x,y,lines,opts={}){
  const {size=22, fill=colors.text, weight='400', anchor='start', lineHeight=1.18} = opts;
  return `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" font-weight="${weight}" text-anchor="${anchor}">` +
    lines.map((ln,i)=>`<tspan x="${x}" dy="${i? size*lineHeight:0}">${esc(ln)}</tspan>`).join('') + `</text>`;
}
function grid(panel, ticks, ymin, ymax, label, unit){
  let s='';
  for(const t of ticks){ const y=yScale(t,ymin,ymax,panel.y0,panel.y1); s += `<line x1="${plotX0}" x2="${plotX1}" y1="${y}" y2="${y}" stroke="${colors.grid}" stroke-width="1.5"/>`; s += text(plotX0-22,y+8,fmt(t),{size:22,fill:'#53606F',anchor:'end'}); }
  s += `<line x1="${plotX0}" x2="${plotX1}" y1="${panel.y1}" y2="${panel.y1}" stroke="${colors.axis}" stroke-width="2"/>`;
  s += `<line x1="${plotX0}" x2="${plotX0}" y1="${panel.y0}" y2="${panel.y1}" stroke="${colors.axis}" stroke-width="2"/>`;
  s += `<text transform="translate(${55},${(panel.y0+panel.y1)/2}) rotate(-90)" font-size="23" fill="#344054" text-anchor="middle">${esc(label)}</text>`;
  return s;
}
function marker(x,y,color,shape='circle'){
  if(shape==='square') return `<rect x="${x-8}" y="${y-8}" width="16" height="16" fill="${color}" stroke="white" stroke-width="3"/>`;
  if(shape==='tri') return `<path d="M${x} ${y-10} L${x-10} ${y+9} L${x+10} ${y+9} Z" fill="${color}" stroke="white" stroke-width="3"/>`;
  return `<circle cx="${x}" cy="${y}" r="9" fill="${color}" stroke="white" stroke-width="3"/>`;
}
function legend(items, x, y){
  let s=''; let cx=x;
  for(const it of items){
    s += `<line x1="${cx}" x2="${cx+42}" y1="${y}" y2="${y}" stroke="${it.color}" stroke-width="6" stroke-dasharray="${it.dash||''}"/>`;
    s += text(cx+54,y+8,it.label,{size:22,fill:'#344054'});
    cx += it.width || 520;
  }
  return s;
}
function callout(x1,y1,x2,y2,lines,color,anchor='start'){
  const tx = anchor==='end'?x2-6:x2+6;
  return `<path d="M${x1} ${y1} L${x2} ${y2}" stroke="${color}" stroke-width="2.2" fill="none" marker-end="url(#arrow-${color.slice(1)})"/>` + multiText(tx,y2-8,lines,{size:21,fill:color,anchor,weight:'600'});
}

const tariff = data.tariff_rates.data;
const tx = tariff.map(d=>periodX(d.period));
const us = tariff.map(d=>d.us_tariff_on_china);
const cn = tariff.map(d=>d.china_tariff_on_us);
const trade = data.bilateral_trade.data;
const years = trade.map(d=>d.year), total=trade.map(d=>d.total_bilateral), imports=trade.map(d=>d.us_imports_from_china), exports=trade.map(d=>d.us_exports_to_china);
const share = data.supply_chain_share.data;
const sy=share.map(d=>d.year), china=share.map(d=>d.china), vietnam=share.map(d=>d.vietnam), india=share.map(d=>d.india), alt=share.map(d=>d.vietnam+d.india);
const events = data.policy_events.data.map(e=>({x:decYear(e.date), ...e}));
const eventLabels = [
  ['2017-08-14',['Section 301','investigation'],'investigation',0.50],
  ['2018-03-22',['$50B tariffs','announced'],'tariff',0.82],
  ['2018-07-06',['List 1–2','25% tariffs'],'tariff',0.50],
  ['2018-09-24',['List 3','$200B'],'tariff',0.82],
  ['2019-05-10',['List 3 raised','to 25%'],'tariff',0.50],
  ['2019-09-01',['List 4A','15%'],'tariff',0.82],
  ['2020-01-15',['Phase One','deal'],'deal',0.50],
  ['2021-10-04',['USTR review','framework'],'review',0.82],
  ['2022-06-20',['Selective exclusions','considered'],'review',0.50],
  ['2024-05-14',['Biden 2024','tariff hikes'],'tariff',0.82],
].map(([date,lines,cat,y])=>({x:decYear(date),lines,cat,y}));

let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<defs>
  <style><![CDATA[
    text { font-family: Inter, "DejaVu Sans", Arial, sans-serif; }
    .smallcaps { letter-spacing: .04em; text-transform: uppercase; }
  ]]></style>
  ${['A33A32','2F5D8C','5B6472','1B9E77'].map(c=>`<marker id="arrow-${c}" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="#${c}"/></marker>`).join('\n')}
</defs>
<rect width="${W}" height="${H}" fill="${bg}"/>
`;

svg += text(110,86,'US–China Trade War Dynamics',{size:52,weight:'800',fill:colors.text});
svg += text(110,132,'Tariff escalation, bilateral trade volumes, and supply chain diversion (2016–2024)',{size:30,fill:colors.sub});
svg += text(110,174,'Single aligned timeline • values trace to source_data.json',{size:22,fill:'#667085'});

// shaded bands
for(const p of [panels.tariff, panels.trade, panels.share]){
  svg += `<rect x="${xScale(2018.45)}" y="${p.y0}" width="${xScale(2020.15)-xScale(2018.45)}" height="${p.y1-p.y0}" fill="${colors.shade}" opacity="0.58"/>`;
  svg += `<rect x="${xScale(2021.75)}" y="${p.y0}" width="${xScale(2024.45)-xScale(2021.75)}" height="${p.y1-p.y0}" fill="${colors.recovery}" opacity="0.50"/>`;
}

// Event timeline
svg += `<line x1="${plotX0}" x2="${plotX1}" y1="${panels.event.y1-40}" y2="${panels.event.y1-40}" stroke="${colors.axis}" stroke-width="3"/>`;
for(const e of events){ const c=e.category==='tariff'?colors.event:e.category==='deal'?colors.deal:colors.review; const x=xScale(e.x); svg += `<line x1="${x}" x2="${x}" y1="${panels.event.y1-70}" y2="${panels.event.y1-10}" stroke="${c}" stroke-width="3" opacity="0.9"/><circle cx="${x}" cy="${panels.event.y1-40}" r="9" fill="${c}" stroke="white" stroke-width="3"/>`; }
for(const e of eventLabels){ const c=e.cat==='tariff'?colors.event:e.cat==='deal'?colors.deal:colors.review; const x=xScale(e.x), y=panels.event.y0 + e.y*(panels.event.y1-panels.event.y0)-5; svg += `<line x1="${x}" x2="${x}" y1="${panels.event.y1-68}" y2="${y+10}" stroke="${c}" stroke-width="1.8" opacity="0.65"/>`; svg += multiText(x,y,e.lines,{size:19,fill:'#2E3440',anchor:'middle',lineHeight:1.1}); }
svg += text(plotX0, panels.event.y1+18, 'Policy event markers',{size:20,fill:'#5F6B7A',weight:'600'});

// reference vertical lines
for(const p of [panels.tariff, panels.trade, panels.share]){
  for(const e of events){ const x=xScale(e.x); svg += `<line x1="${x}" x2="${x}" y1="${p.y0}" y2="${p.y1}" stroke="#8B95A1" stroke-width="1.2" opacity="0.25"/>`; }
}

// Tariff panel
svg += text(plotX0, panels.tariff.y0-48, '1  Tariff escalation',{size:28,weight:'800'});
svg += legend([{color:colors.us,label:'US tariff on Chinese imports',width:560},{color:colors.cn,label:'China retaliatory tariff on US imports',width:640}], plotX0, panels.tariff.y0-18);
svg += grid(panels.tariff,[0,5,10,15,20,25],0,29,'Average effective tariff rate (%)');
svg += `<path d="${stepPath(tx,us,0,29,panels.tariff.y0,panels.tariff.y1)}" stroke="${colors.us}" stroke-width="7" fill="none" stroke-linejoin="round"/>`;
svg += `<path d="${stepPath(tx,cn,0,29,panels.tariff.y0,panels.tariff.y1)}" stroke="${colors.cn}" stroke-width="7" fill="none" stroke-linejoin="round"/>`;
tx.forEach((x,i)=>{ svg += marker(xScale(x), yScale(us[i],0,29,panels.tariff.y0,panels.tariff.y1), colors.us); svg += marker(xScale(x), yScale(cn[i],0,29,panels.tariff.y0,panels.tariff.y1), colors.cn); });
svg += text(xScale(2018.63), panels.tariff.y0+32, 'Stepwise escalation window',{size:22,weight:'800',fill:'#6E332E'});
svg += text(xScale(2022.75), panels.tariff.y0+32, 'Review / persistence phase',{size:22,weight:'800',fill:'#526B83',anchor:'middle'});
svg += callout(xScale(2018.75), yScale(12,0,29,panels.tariff.y0,panels.tariff.y1), xScale(2018.18), yScale(17.2,0,29,panels.tariff.y0,panels.tariff.y1), ['+8.2 pts','2018 H1→H2'], colors.us);
svg += callout(xScale(2024.25), yScale(25.4,0,29,panels.tariff.y0,panels.tariff.y1), xScale(2023.35), yScale(27,0,29,panels.tariff.y0,panels.tariff.y1), ['2024 H1: 25.4%'], colors.us);

// Trade panel
svg += text(plotX0, panels.trade.y0-48, '2  Bilateral trade volume',{size:28,weight:'800'});
svg += legend([{color:colors.trade,label:'Total bilateral trade',width:430},{color:colors.import,label:'US imports from China',dash:'12 10',width:430},{color:colors.export,label:'US exports to China',dash:'4 8',width:420}], plotX0, panels.trade.y0-18);
